from mcp.server.fastmcp import FastMCP

mcp = FastMCP("inventory-server")

@mcp.tool()
def check_stock(sku: str) -> str:
    """Returns the available stock for a given SKU. Use it when
    asked about the availability of a specific product."""
    stock = database.get(sku, 0)
    return f"SKU {sku} has {stock} units available"

if __name__ == "__main__":
    mcp.run()

from pydantic import Field

@mcp.tool(description="Replaces a portion of text in an existing document.")
def edit_document(
    doc_id: str = Field(description="Id of the document to edit"),
    old_text: str = Field(description="Text to replace. Must match exactly, including whitespace."),
    new_text: str = Field(description="Text that replaces the previous one"),
):
    if doc_id not in docs:
        raise ValueError(f"Document {doc_id} does not exist")
    docs[doc_id] = docs[doc_id].replace(old_text, new_text)

@mcp.resource("config://return-policy")
def return_policy() -> str:
    return open("policy.md").read()

